def _parse(v):
    v = v.split('+', 1)[0]
    if '-' in v:
        core, pre = v.split('-', 1)
        pre = pre.split('.')
    else:
        core, pre = v, None
    return [int(x) for x in core.split('.')], pre

def _cid(a, b):
    an, bn = a.isdigit(), b.isdigit()
    if an and bn:
        ia, ib = int(a), int(b)
        return (ia > ib) - (ia < ib)
    if an:
        return -1
    if bn:
        return 1
    return (a > b) - (a < b)

def so_sanh_semver(a: str, b: str) -> int:
    na, pa = _parse(a)
    nb, pb = _parse(b)
    for x, y in zip(na, nb):
        if x != y:
            return -1 if x < y else 1
    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1
    for x, y in zip(pa, pb):
        c = _cid(x, y)
        if c:
            return c
    if len(pa) == len(pb):
        return 0
    return -1 if len(pa) < len(pb) else 1

